INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem": "古诗词中“恰似一江春水向东流”，这里的水是由（　）面流向（　）面。", "options": null}', '西；东', '水向东流，说明水从西边流向东边（东的对面是西）。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p033.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem": "下午放学，贝贝朝着太阳方向走，他的后面是（　）面，右面是（　）面。", "options": null}', '东；北', '下午太阳在西边，贝贝面向西：后面是东；面向西时左边是南、右边是北，所以右面是北。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p033.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem": "爸爸开车向南行驶，在十字路口（红绿灯处）左转了，此时他向（　）面行驶。", "options": null}', '东', '面向南时，左手边是东，左转后车头朝东行驶。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p033.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem": "傍晚，乐乐和同学一起看日落，欣赏美丽的晚霞，这时，他们面向（　）方，右边是（　）方。", "options": null}', '西；北', '傍晚太阳在西边，看日落即面向西；面向西时左边是南、右边是北。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p033.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem": "小海从家走路去超市，先向西走，又向北走。他想沿原路回家，应先向（　）走，再向（　）走。", "options": null}', '南；东', '原路返回方向与去时相反、顺序倒过来：去时先西后北，返回先向南（北的反方向）走，再向东（西的反方向）走。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p033.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem": "这是红红卧室的示意图：推开红红卧室的门，正好面对着窗户，窗户在南面的墙上。门在（　）面的墙上。", "options": null}', '北', '门正对窗户，窗户在南墙上，门就在相对的北墙上。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p033.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem": "街道示意图中（上北下南、左西右东）：欢欢家在邮局的北面（同一条街），明明家在植物园的西面（同一排）。欢欢从家到邮局是向（　）走；明明从家到植物园是向（　）走。", "options": null}', '南；东', '邮局在欢欢家的南面，所以向南走；植物园在明明家的东面，所以向东走。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p033.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem": "小朋友们正在进行队列训练，他们面朝南站，老师要求他们先向右转1次，再向左转2次，这时他们面朝（　）；如果再向后转3次，这时他们面朝（　）。", "options": null}', '东；西', '面朝南，右转1次后朝西；再左转2次：西→南→东，即朝东。向后转3次相当于转3个180°（共540°，等效180°），朝东的对面朝西。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p034.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem": "在野外，可以通过观察树的年轮来辨别方向。树的年轮较密处向着（　）面，较疏处向着（　）面。", "options": null}', '北；南', '北半球南面日照充足、树木生长快，年轮较宽（疏）；北面日照少、生长慢，年轮较密。所以年轮密处朝北、疏处朝南。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p034.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem": "看图填空（图中上北下南）：电影院在医院的正北面，图书馆在医院的正西面；文文家在图书馆的正北面（和电影院同一排），苗家在医院的正东面。那么苗苗家的西面有（　）和（　）；电影院在文文家的（　）面。", "options": null}', '医院、图书馆；东', '苗家在医院的东面，所以苗家的西面紧挨着医院，再往西是图书馆；文文家在图书馆北面，与电影院同一排且在电影院西侧，所以电影院在文文家的东面。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p035.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 1, '{"stem": "二（1）班黑板在教室的西面，那么老师讲课时面向（　）。", "options": ["A.东", "B.南", "C.西"]}', 'C', '老师讲课要面向黑板，黑板在西墙，所以面向西。选 C。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p034.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem": "如图，小区示意图中：游泳池的北面是1号楼、南面是2号楼、东面是健身中心。那么（　）在游泳池的西面。", "options": ["A.2号楼", "B.健身中心", "C.文化中心"]}', 'C', '游泳池北=1号楼、南=2号楼、东=健身中心，剩余的文化中心在西面（图中文化中心正在游泳池西侧）。选 C。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p034.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem": "刮了一夜北风，黄叶落了一地，落在（　）面的黄叶多一些。", "options": ["A.南", "B.西", "C.东"]}', 'A', '北风从北边吹来，落叶被吹向南边，南面的黄叶多。选 A。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p034.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem": "“立竿测日影”是我国古代利用太阳照射的影子来测量时间的一种方法。如图，影子在竹竿的西面，那么太阳在竹竿的（　）面。", "options": ["A.东", "B.西", "C.南"]}', 'A', '影子方向与太阳方向相反：影子在西，太阳在东。选 A。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p034.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 1, '{"stem": "人的影子在西方，太阳应在东方。（　）", "options": null}', '√', '影子与太阳方向相反：影子在西，太阳就在东。说法正确。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p035.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 1, '{"stem": "在森林中可以利用树叶的疏密来识别方向。（　）", "options": null}', '√', '南面光照充足枝叶茂密，北面枝叶稀疏，可借此辨认南北。说法正确。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p035.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 1, '{"stem": "小红面向南时，她的左面是北面。（　）", "options": null}', '×', '面向南时：左面是东、右面是西、后面是北。她的左面应是东面，说法错误。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p035.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 3, '{"stem": "一天早晨，丽丽面向镜子，在镜子中看到了正在升起的太阳，此时她的前面是东。（　）", "options": null}', '×', '早晨太阳在东边，镜中能看到太阳说明镜面朝东（镜子在西墙）；人面向镜子即面向西，前面是西而不是东。说法错误。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p035.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 2, '{"stem": "一条小河从西向东流，一群鱼逆流而上，鱼尾指向西面。（　）", "options": null}', '×', '水从西向东流，逆流即迎着水来的方向（向西）游，鱼头朝西、鱼尾朝东。说鱼尾指向西面是错的。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p035.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用', 3, '{"stem": "看图回答问题：某小学举行安全疏散演练，假如你所在的8班教室里发生了火情，你该如何逃生？逃生的过程中，在保证安全的情况下，你该如何通知其他班级？（紧急疏散时不乘电梯，应从最近的紧急出口撤离）", "options": null}', '沿疏散通道向最近的紧急出口撤离，不乘电梯，可用湿毛巾捂住口鼻、弯腰低姿、有序快速撤离；通知其他班级：按下/拉响火灾报警器、大声呼喊提醒相邻班级、请老师广播通知或拨打119报警。', '开放题，答出要点即可：①逃生走疏散通道、向最近紧急出口撤离、不乘电梯；②保护自己（湿毛巾捂口鼻、弯腰低姿、不拥挤）；③通知他人（报警器/呼喊/广播/119）。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p036.png"]');
